-- Neural semantic embeddings generated with sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2 (384 dimensions).
-- Source text: name and people columns from people.csv.
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS public.people (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name text NOT NULL,
    people text NOT NULL,
    embedding vector(384) NOT NULL
);

CREATE INDEX IF NOT EXISTS people_embedding_hnsw_idx
    ON public.people USING hnsw (embedding vector_cosine_ops);

